7: 
8: const LastPurchasesFragment = () => {
9:   const { data: compras } = useGetCompras();
10: 
11:   if (!compras || compras.length === 0) {
12:     return <></>;
13:   }
14: 
15:   const dadosDaEntrega = (compra) => {
16:     if (compra.deliveredAt) {
17:       return `Entrega realizada em ${new Date(
18:         compra.deliveredAt
19:       ).toLocaleDateString()}.`;
20:     }
21: 
22:     return (
23:       <span style={{ color: "green", fontWeight: 500 }}>
24:         Chega dia {new Date(compra.estimatedDeliveryDate).toLocaleDateString()}.
25:       </span>
26:     );
27:   };
28: 
29:   return (
30:     <div className="d-flex flex-column justify-content-center mb-4">
31:       <div className="d-flex flex-row align-items-center">
32:         <Typography.Title className="float-start">
33:           Últimas Compras
34:         </Typography.Title>
35:         <Anchor.Primary className="ms-4" to={routes.COMPRAS}>
36:           Ver todas
37:         </Anchor.Primary>
38:       </div>
39:       <div className="d-flex flex-wrap mt-3 justify-content-start">
40:         {compras.slice(0, 4).map((compra) => (
41:           <Card style={{ width: "18rem" }} className="card" key={compra.id}>
42:             <div className="card-body">
43:               <h5 className="card-title">
44:                 Feita em {new Date(compra.createdAt).toLocaleDateString()}
45:               </h5>
46:               <h1 className="card-title">{currencyFormatter(compra.total)}</h1>
47:               {dadosDaEntrega(compra)}
48:             </div>
49:             <ul className="list-group list-group-flush">
50:               <li className="list-group-item d-flex justify-content-center">
51:                 <Anchor.Primary to={routes.COMPRA.replace(":id", compra.id)}>
52:                   Ver detalhes
53:                 </Anchor.Primary>
54:               </li>
55:             </ul>
56:           </Card>
57:         ))}
58:       </div>
59:       <hr className="mt-4" />
60:     </div>
61:   );
62: };
63: 
64: export default LastPurchasesFragment;

1: import React, { useEffect, useState } from "react";
2: import { Details, Title, ValorEntrega } from "./styles";
3: import { Button, LoadingIcon } from "@nabstore/styleguide";
4: import { currencyFormatter as currencyFormat } from "@nabstore/utils";
5: import { faTruck } from "@fortawesome/free-solid-svg-icons";
6: import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
7: import useGetDeliveryEstimative from "../../hooks/useGetDeliveryEstimative";
8: import { notification } from "antd";
9: 
10: const DeliveryEstimateFragment = () => {
11:   const [cepEntrega, setCepEntrega] = useState("");
12:   const {
13:     getEstimative,
14:     data: entrega,
15:     isLoading,
16:     error,
17:   } = useGetDeliveryEstimative();
18: 
19:   const handleClick = () => {
20:     getEstimative(cepEntrega);
21:   };
22: 
23:   const handleCepChange = (e) => {
24:     let value = e.target.value.replace(/\D/g, "");
25:     value = value.replace(/^(\d{5})(\d)/, "$1-$2");
26:     value = value.slice(0, 9);
27:     setCepEntrega(value);
28:   };
29: 
30:   useEffect(() => {
31:     if (error) {
32:       const args = {
33:         message: "Oops...",
34:         description: "Erro ao estimar entrega.",
35:         duration: 2,
36:       };
37:       notification.error(args);
38:     }
39:   }, [error]);
40: 
41:   return (
42:     <div className="p-3 card-body ">
43:       <Title>Entrega</Title>
44: 
45:       <div className="p-3 card-body d-flex justify-content-center">
46:         <input
47:           type="text"
48:           id="cepEntrega"
49:           className="form-control"
50:           placeholder="00000-000"
51:           value={cepEntrega}
52:           onChange={handleCepChange}
53:         />
54:         <Button.Primary
55:           width="45%"
56:           margin="0 10px"
57:           disabled={cepEntrega === ""}
58:           onClick={handleClick}
59:         >
60:           {isLoading ? <LoadingIcon.Oval stroke="#2f2f2f" /> : "Calcular frete"}
61:         </Button.Primary>
62:       </div>
63: 
64:       {entrega && entrega.estimatedDeliveryDate ? (
65:         <div className="ms-3 me-3 card-body d-flex justify-content-between align-items-emd">
66:           <Details>
67:             <FontAwesomeIcon className="me-2" icon={faTruck} />
68:             Previsão de entrega dia{" "}
69:             {new Date(entrega.estimatedDeliveryDate).toLocaleDateString()}.
70:           </Details>
71:           <ValorEntrega>
72:             {entrega.preco === 0 ? "Grátis" : currencyFormat(entrega.preco)}
73:           </ValorEntrega>
74:         </div>
75:       ) : (
76:         <></>
77:       )}
78:     </div>
79:   );
80: };
81: 
82: export default DeliveryEstimateFragment;

1: import React, { useEffect, useState } from "react";
