11: 
12: const Checkout = ({ cleanCartAction }) => {
13:   const { user, cart } = useSelector((state) => ({
14:     cart: state.cart,
15:     user: state.user,
16:   }));
17:   const [total, setTotal] = useState(0);
18:   const dispatch = useDispatch();
19:   const navigate = useNavigate();
20:   const { createCompra, data, isLoading, error } = useCreateCompra();
21: 
22:   useEffect(() => {
23:     setTotal(
24:       cart.produtos.reduce(
25:         (prev, actual) => prev + actual.qtd * actual.precoUnit,
26:         0
27:       )
28:     );
29:   }, [cart]);
30: 
31:   useEffect(() => {
32:     if (data) {
33:       const args = {
34:         message: "OBRIGADO",
35:         description: "Compra realizada com sucesso!",
36:         duration: 2,
37:       };
38:       notification.success(args);
39:       dispatch(cleanCartAction());
40:       navigate(routes.HOME);
41:     }
42:   }, [data]);
43: 
44:   useEffect(() => {
45:     if (error) {
46:       const args = {
47:         message: "Oops...",
48:         description: "Erro ao finalizar compra.",
49:         duration: 2,
50:       };
51:       notification.error(args);
52:     }
53:   }, [error]);
54: 
55:   const handleComprar = () => {
56:     createCompra(
57:       user.id,
58:       cart.cartaoEscolhido.id,
59:       cart.enderecoEscolhido.id,
60:       cart.produtos.map((prod) => ({
61:         produtoId: prod.id,
62:         quantidade: prod.qtd,
63:         precoUnit: prod.precoUnit,
64:       }))
65:     );
66:   };
67: 
68:   if (
69:     !cart ||
70:     !cart.cartaoEscolhido ||
71:     !cart.enderecoEscolhido ||
72:     !cart.produtos ||
73:     !cart.produtos.length === 0
74:   ) {
75:     return (
76:       <div className="container">
77:         <div className="d-flex justify-content-center">
78:           <Typography.Title>Confirmar Compra</Typography.Title>
79:         </div>
80: 
81:         <div className="d-flex justify-content-center mt-5">
82:           <Typography.Subtitle>
83:             Ops, parece que os dados da compra estão incompletos =(.
84:           </Typography.Subtitle>
85:         </div>
86:       </div>
87:     );
88:   }
89: 
90:   return (
91:     <div className="container">
92:       <Anchor.GoBack path={routes.ENDERECOS} text="Voltar aos endereços" />
93: 
94:       <div className="d-flex justify-content-center">
95:         <Typography.Title>Confirmar Compra</Typography.Title>
96:       </div>
97: 
98:       <div className="d-flex flex-row">
99:         <Card className="card" style={{ width: "60%" }}>
100:           <Typography.Subtitle className="m-2 mb-4" bold>
101:             Produtos
102:           </Typography.Subtitle>
103:           {cart.produtos.map((prod) => (
104:             <div
105:               className="d-flex flex-row justify-content-between p-2"
106:               key={prod.id}
107:             >
108:               <Info>
109:                 {prod.qtd}x {prod.nome}
110:               </Info>
111:               <Value bold>{currencyFormatter(prod.qtd * prod.precoUnit)}</Value>
112:             </div>
113:           ))}
114: 
115:           <hr />
116: 
117:           <div className="mt-3 mb-3 d-flex  flex-row justify-content-between">
118:             <Info>Taxa de Entrega:</Info>
119:             <Value bold style={{ color: "green" }}>
120:               Grátis
121:             </Value>
122:           </div>
123: 
124:           <hr />
125: 
126:           <div className="mt-3 mb-3 d-flex  flex-row justify-content-between">
127:             <Info>Cartão:</Info>
128:             <Value bold style={{ color: "green" }}>
129:               {cart.cartaoEscolhido?.apelido}
130:             </Value>
131:           </div>
132: 
133:           <hr />
134: 
135:           <div className="mt-3 mb-3 d-flex align-items-center flex-row justify-content-between">
136:             <Info style={{ color: "#2f2f2f" }}>Valor total:</Info>
137:             <Value bold style={{ fontSize: 32 }}>
138:               {currencyFormatter(total)}
139:             </Value>
140:           </div>
141:           <Button.Secondary onClick={handleComprar}>
142:             {isLoading ? (
143:               <LoadingIcon.Oval stroke="#2f2f2f" />
144:             ) : (
145:               "Finalizar Compra"
146:             )}
147:           </Button.Secondary>
148:         </Card>
149: 
150:         <Card className="card" style={{ width: "40%", height: "50%" }}>
151:           <Typography.Subtitle className="m-2 mb-4" bold>
152:             Entrega
153:           </Typography.Subtitle>
154:           <Info>
155:             {cart.enderecoEscolhido?.logradouro},{" "}
156:             {cart.enderecoEscolhido?.bairro} - {cart.enderecoEscolhido?.numero}
157:           </Info>
158:           <Info>
159:             {cart.enderecoEscolhido?.cidade} - {cart.enderecoEscolhido?.uf}
160:           </Info>
161:           <Info>CEP: {cart.enderecoEscolhido?.cep}</Info>
162: 
163:           <hr />
164: 
165:           <Value>Previsão de entrega até semana que vem</Value>
166:         </Card>
167:       </div>
168:     </div>
169:   );
170: };
171: 
172: export default Checkout;

