12: const Cartoes = ({ selectCartAction }) => {
13:   const dispatch = useDispatch();
14:   const navigate = useNavigate();
15:   const { data: cartoes, isLoading, error } = useGetCartoes();
16:   const [isCreateCartaoModalOpen, setIsCreateCartaoModalOpen] = useState(false);
17: 
18:   const handleSelect = (cartao) => {
19:     dispatch(selectCartAction(cartao));
20:     navigate(routes.ENDERECOS);
21:   };
22: 
23:   const CartoesList = () => {
24:     if (isLoading || !cartoes) {
25:       return (
26:         <div className="d-flex flex-column align-items-center">
27:           <LoadingIcon.Oval className="mt-5" stroke="#2f2f2f" />
28:         </div>
29:       );
