31: 
32:     if (error) {
33:       return (
34:         <div className="d-flex flex-column align-items-center mt-5">
35:           <Typography.Subtitle>Erro ao carregar cartões.</Typography.Subtitle>
36:         </div>
37:       );
38:     }
39: 
40:     if (cartoes.length === 0) {
41:       return (
42:         <div className="d-flex flex-column align-items-center mt-5">
43:           <Typography.Subtitle>Você ainda não tem cartões cadastrados.</Typography.Subtitle>
44:         </div>
45:       );
46:     }
47: 
48:     return (
49:       <div className="d-flex flex-column align-items-center mb-5">
50:         {cartoes.map((cartao) => (
51:           <CartaoItem
52:             key={cartao.id}
53:             cartao={cartao}
54:             handleSelect={handleSelect}
55:           />
56:         ))}
57:       </div>
58:     );
59:   };
60: 
61:   return (
62:     <div className="container pb-5">
63:       <CreateCartaoModal
64:         handleClose={() => setIsCreateCartaoModalOpen(false)}
65:         showModal={isCreateCartaoModalOpen}
66:       />
67: 
68:       <Anchor.GoBack path={routes.CART} text="Voltar ao carrinho" />
69: 
70:       <div className="float-end">
71:         <Button.Primary onClick={() => setIsCreateCartaoModalOpen(true)}>
72:           <FontAwesomeIcon className="me-2" icon={faPlusCircle} /> Novo Cartão
73:         </Button.Primary>
74:       </div>
75: 
76:       <div className="d-flex justify-content-center mt-4">
77:         <Typography.Title>Cartões</Typography.Title>
78:       </div>
79: 
80:       <CartoesList />
81: 
82:     </div>
83:   );
84: };
85: 
86: export default Cartoes;

